/**
 * Help, written once: the app's Help screen and the website's help page
 * (site/help.html, generated by `npm run help -w @wave-exit/app`) both render
 * this. Plain words for accountants and bookkeepers; no technical terms.
 * Wave's button labels are quoted exactly as Wave shows them.
 */

export type Block =
  | { p: string }
  | { list: string[] }
  | { steps: string[] }
  | { table: { head: string[]; rows: string[][] } }
  | { note: string };

export interface HelpTopic {
  id: string;
  title: string;
  /** One line shown in the topic list. */
  summary: string;
  blocks: Block[];
}

export interface HelpSection {
  title: string;
  topics: HelpTopic[];
}

